INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass eine Standortverbindung immer über das öffentliche Internet erfolgt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch private Netze möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend Internet"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird oft für solche Verbindungen genutzt?', 3, '[{"text": "IPsec", "correct": true, "because": "Sichert Tunnel"}, {"text": "FTP", "correct": false, "because": "Für Dateitransfer"}, {"text": "SMTP", "correct": false, "because": "Für E-Mails"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale sind für eine sichere Standortverbindung wichtig?', 5, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Daten"}, {"text": "Authentifizierung", "correct": true, "because": "Sichert Identität"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Sekundär"}, {"text": "Farbcodierung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Solche Verbindungen nutzen Tunnel. b) Sie sind immer für einzelne Nutzer gedacht.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, für Netzwerke"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Einrichtung einer solchen Verbindung?', 4, '[{"text": "Schlüsselmanagement", "correct": false, "because": "Sichert Verschlüsselung"}, {"text": "Netzwerkkonfiguration", "correct": false, "because": "Bestimmt Routing"}, {"text": "Routerfarbe", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine solche Verbindung immer IPsec nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch andere Protokolle möglich"}, {"text": "Ja", "correct": false, "because": "Nicht zwingend IPsec"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gerät wird typischerweise für solche Verbindungen konfiguriert?', 4, '[{"text": "Router", "correct": true, "because": "Verwaltet Tunnel"}, {"text": "Switch", "correct": false, "because": "Für lokale Netze"}, {"text": "Access Point", "correct": false, "because": "Für WLAN"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Verbindungen immer langsam sind. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit abhängig von Infrastruktur"}, {"text": "Ja", "correct": false, "because": "Kann optimiert werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist eine solche Verbindung dasselbe wie ein Remote-Access-VPN?', 2, '[{"text": "Nein", "correct": true, "because": "Verbindet Netzwerke, nicht Nutzer"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle unterstützen solche Verbindungen?', 5, '[{"text": "IPsec", "correct": true, "because": "Sichert Tunnel"}, {"text": "L2TP", "correct": true, "because": "Kombiniert mit IPsec"}, {"text": "HTTP", "correct": false, "because": "Für Web"}, {"text": "FTP", "correct": false, "because": "Für Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Einrichtung einer solchen Verbindung?', 4, '[{"text": "Sicherheitskonfiguration", "correct": true, "because": "Schützt Daten"}, {"text": "Schnelle Einrichtung", "correct": false, "because": "Sicherheit wichtiger"}, {"text": "Routerdesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Solche Verbindungen verbinden Netzwerke. b) Sie sind immer unverschlüsselt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Verschlüsselung Standard"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine sichere Standortverbindung?', 3, '[{"text": "Verschlüsselung", "correct": false, "because": "Schützt Daten"}, {"text": "Authentifizierung", "correct": false, "because": "Sichert Identität"}, {"text": "Farbliches Branding", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich die Verbindung zwischen zwei Büros sichere?', 4, '[{"text": "IPsec-Tunnel mit Verschlüsselung einrichten", "correct": true, "because": "Sichert Kommunikation"}, {"text": "Ohne Verschlüsselung verbinden", "correct": false, "because": "Unsicher"}, {"text": "Nur Passwort setzen", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass solche Verbindungen keine Firewall brauchen. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Firewall ergänzt Schutz"}, {"text": "Ja", "correct": false, "because": "Firewall empfohlen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip schützt die Datenintegrität in einer solchen Verbindung?', 4, '[{"text": "Hash-Funktionen", "correct": true, "because": "Erkennen Manipulation"}, {"text": "Schnelle Übertragung", "correct": false, "because": "Kein Sicherheitsfaktor"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Verbindet eine solche Verbindung einzelne Geräte?', 2, '[{"text": "Nein", "correct": true, "because": "Verbindet ganze Netzwerke"}, {"text": "Ja", "correct": false, "because": "Netzwerkübergreifend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet eine solche Verbindung?', 5, '[{"text": "Sichere Kommunikation", "correct": true, "because": "Schützt Daten"}, {"text": "Einheitliches Netzwerk", "correct": true, "because": "Vereint Standorte"}, {"text": "Bunte Visuals", "correct": false, "because": "Kein Vorteil"}, {"text": "Hohe Speicherkapazität", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Verwaltung einer solchen Verbindung unwichtig?', 3, '[{"text": "Schlüsselmanagement", "correct": false, "because": "Sichert Verschlüsselung"}, {"text": "Protokollierung", "correct": false, "because": "Erkennt Probleme"}, {"text": "Routergewicht", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich eine solche Verbindung einrichte?', 4, '[{"text": "Router konfigurieren, IPsec aktivieren", "correct": true, "because": "Sichert Tunnel"}, {"text": "Nur Kabel verbinden", "correct": false, "because": "Fehlt Sicherheit"}, {"text": "Ohne Konfiguration", "correct": false, "because": "Unsicher"}]');
